package com.fitpulse.model.entity;
import com.fitpulse.model.enums.*; import jakarta.persistence.*; import java.util.*;
@Entity @Table(name="program_templates") public class ProgramTemplate { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id;
 @ManyToOne private Trainer author;
 public Trainer getAuthor(){return author;} public void setAuthor(Trainer v){author=v;}
 @Column(nullable=false,length=150) private String name; @Enumerated(EnumType.STRING) @Column(nullable=false,length=30) private FitnessGoal goal; @Enumerated(EnumType.STRING) @Column(nullable=false,length=30) private ExperienceLevel experience; private int trainingDays; @Enumerated(EnumType.STRING) @Column(nullable=false,length=30) private TrainingLocation location; @Column(nullable=false,length=1500) private String description; private boolean active=true; @OneToMany(mappedBy="template",cascade=CascadeType.ALL) @OrderBy("dayNumber, sortOrder") private List<ProgramTemplateItem> items=new ArrayList<>(); public Long getId(){return id;} public String getName(){return name;} public String getCategoryLabel(){return switch(goal){case FAT_LOSS -> "За отслабване";case MUSCLE -> "За мускулна маса";case STRENGTH -> "За сила";case MOBILITY -> "За мобилност";case ENDURANCE -> "За издръжливост";case PERFORMANCE -> "За спортна форма";default -> experience==ExperienceLevel.BEGINNER?"За начинаещи":"За обща форма";};}
 public String getCategoryIcon(){return switch(goal){case FAT_LOSS -> "flame";case MUSCLE -> "program";case STRENGTH -> "bolt";case MOBILITY -> "mobility";case ENDURANCE -> "heart";case PERFORMANCE -> "target";default -> "progress";};}
 public String getPlaceLabel(){return location==TrainingLocation.HOME?"Вкъщи":"Във фитнес зала";}
 public String getDisplayName(){return name.replaceFirst("\\s+\\d+\\s+дни$", "");} public void setName(String v){name=v;} public FitnessGoal getGoal(){return goal;} public void setGoal(FitnessGoal v){goal=v;} public ExperienceLevel getExperience(){return experience;} public void setExperience(ExperienceLevel v){experience=v;} public int getTrainingDays(){return trainingDays;} public void setTrainingDays(int v){trainingDays=v;} public TrainingLocation getLocation(){return location;} public void setLocation(TrainingLocation v){location=v;} public String getDescription(){return description;} public void setDescription(String v){description=v;} public boolean isActive(){return active;} public void setActive(boolean v){active=v;} public List<ProgramTemplateItem> getItems(){return items;} }
